using System.IO;
using Microsoft.EntityFrameworkCore;
using AshkanLedgerPro.Models;
namespace AshkanLedgerPro.Data;
public class LedgerDb : DbContext {
 public DbSet<PaymentCheck> PaymentChecks => Set<PaymentCheck>();
 public DbSet<TreasuryTransaction> TreasuryTransactions => Set<TreasuryTransaction>();
 public DbSet<AshkanLedgerPro.Security.AppUser> AppUsers => Set<AshkanLedgerPro.Security.AppUser>();
 public DbSet<PurchaseInvoice> PurchaseInvoices => Set<PurchaseInvoice>(); public DbSet<PurchaseInvoiceLine> PurchaseInvoiceLines => Set<PurchaseInvoiceLine>();
 public DbSet<SalesInvoice> SalesInvoices => Set<SalesInvoice>(); public DbSet<SalesInvoiceLine> SalesInvoiceLines => Set<SalesInvoiceLine>();
 public DbSet<StockMovement> Movements => Set<StockMovement>(); public DbSet<BusinessPartner> Partners => Set<BusinessPartner>(); public DbSet<StockItem> Stock => Set<StockItem>();
 public DbSet<Account> Accounts => Set<Account>(); public DbSet<JournalEntry> Entries => Set<JournalEntry>(); public DbSet<JournalLine> Lines => Set<JournalLine>();
 protected override void OnConfiguring(DbContextOptionsBuilder b) { var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AshkanLedgerPro"); Directory.CreateDirectory(dir); b.UseSqlite($"Data Source={Path.Combine(dir,"ledger.db")}"); }
 protected override void OnModelCreating(ModelBuilder b) { b.Entity<PaymentCheck>().Property(x=>x.Amount).HasConversion(v=>v.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture),v=>decimal.Parse(v,System.Globalization.CultureInfo.InvariantCulture)); b.Entity<PaymentCheck>().HasOne(x=>x.Partner).WithMany().HasForeignKey(x=>x.PartnerId).OnDelete(DeleteBehavior.Restrict); b.Entity<TreasuryTransaction>().Property(x=>x.Amount).HasConversion(v=>v.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture),v=>decimal.Parse(v,System.Globalization.CultureInfo.InvariantCulture)); b.Entity<TreasuryTransaction>().HasOne(x=>x.Partner).WithMany().HasForeignKey(x=>x.PartnerId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseInvoice>().HasOne(x=>x.Partner).WithMany().HasForeignKey(x=>x.PartnerId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseInvoiceLine>().HasOne<PurchaseInvoice>().WithMany(x=>x.Items).HasForeignKey(x=>x.PurchaseInvoiceId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseInvoiceLine>().HasOne(x=>x.StockItem).WithMany().HasForeignKey(x=>x.StockItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseInvoice>().Property(x=>x.Total).HasConversion<double>(); b.Entity<PurchaseInvoiceLine>().Property(x=>x.UnitCost).HasConversion<double>(); b.Entity<PurchaseInvoiceLine>().Property(x=>x.LineTotal).HasConversion<double>(); b.Entity<SalesInvoice>().HasOne(x=>x.Partner).WithMany().HasForeignKey(x=>x.PartnerId).OnDelete(DeleteBehavior.Restrict); b.Entity<SalesInvoiceLine>().HasOne(x=>x.StockItem).WithMany().HasForeignKey(x=>x.StockItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<SalesInvoiceLine>().HasOne<SalesInvoice>().WithMany(x=>x.Items).HasForeignKey(x=>x.SalesInvoiceId).OnDelete(DeleteBehavior.Restrict); foreach(var property in new[]{nameof(SalesInvoice.Subtotal),nameof(SalesInvoice.Discount),nameof(SalesInvoice.Tax),nameof(SalesInvoice.Total)})b.Entity<SalesInvoice>().Property<decimal>(property).HasConversion<double>(); b.Entity<SalesInvoiceLine>().Property(x=>x.UnitPrice).HasConversion<double>(); b.Entity<SalesInvoiceLine>().Property(x=>x.LineTotal).HasConversion<double>(); b.Entity<StockMovement>().HasOne(x=>x.StockItem).WithMany().HasForeignKey(x=>x.StockItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<BusinessPartner>().HasIndex(x=>x.Name); b.Entity<StockItem>().HasIndex(x=>x.Sku).IsUnique(); b.Entity<StockItem>().Property(x=>x.UnitPrice).HasConversion<double>(); b.Entity<Account>().HasIndex(x=>x.Code).IsUnique(); b.Entity<JournalLine>().Property(x=>x.Debit).HasConversion<double>(); b.Entity<JournalLine>().Property(x=>x.Credit).HasConversion<double>(); }
}
